// Merge the two fetched config files into one item every downstream node reads via
// $('parse_board_config').first().json. board_intake.json describes the board and the
// defaults an imported row carries; curator_config.json owns cancel_after_days, because the
// ceiling is one policy for both queues and a second copy would be a second thing to keep
// in step. A missing file degrades to the defaults; a malformed one is loud, the same way
// parse_curator_config treats its file.
const readText = (raw) => (raw == null ? '' : String(raw));
const parse = (raw, name) => {
  if (!raw) return {};
  try {
    return JSON.parse(raw);
  } catch (e) {
    throw new Error('datasets/' + name + ' is not valid JSON: ' + e.message);
  }
};
const b = parse(readText($('download_board_config').first().json.output), 'board_intake.json');
const c = parse(readText($('download_curator_config').first().json.output), 'curator_config.json');
const str = (v, d) => (v == null || String(v).trim() === '' ? d : String(v).trim());
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const def = b.defaults && typeof b.defaults === 'object' ? b.defaults : {};

const out = {
  owner: str(b.owner, 'datahub-local'),
  repo: str(b.repo, 'datahub-local'),
  label: str(b.label, 'post'),
  state: str(b.state, 'open'),
  categories: str(def.categories, 'General'),
  asset_types: str(def.asset_types, 'image,svg'),
  max_words: num(def.max_words, 1200),
  priority: str(def.priority, 'MEDIUM'),
  // The level is a person's decision, so the intake only carries the configured default;
  // a mistyped value is refused by the article lane, which owns the vocabulary.
  audience: str(def.audience, 'NONE').toUpperCase(),
  cancel_after_days: Math.max(1, num(c.cancel_after_days, 7)),
  run_at: new Date().toISOString(),
};
console.log(
  'parse_board_config: ' + out.owner + '/' + out.repo + ' label=' + out.label + ' cancel_after=' +
    out.cancel_after_days + 'd'
);
return [{ json: out }];

// One item per issue the queue does not already carry. ENTRY_ID is stable (gh-<number>), so
// the same open issue is skipped on every later run; LINK is checked too, in case a human
// added the same idea by hand. Pull requests come back from the issues endpoint as well and
// are dropped by their own marker - a PR is not an article idea.
const cfg = $('parse_board_config').first().json;
const issues = $('list_board_issues').all().map((i) => i.json);
const queue = $('read_article_queue').all().map((i) => i.json);
const seenId = new Set(queue.map((r) => String(r.ENTRY_ID || '').trim()).filter(Boolean));
const seenLink = new Set(queue.map((r) => String(r.LINK || '').trim()).filter(Boolean));
const runAt = cfg.run_at;

const rows = [];
for (const it of issues) {
  if (!it || it.pull_request) continue;
  const number = it.number;
  if (number == null || number === '') continue;
  const entry = 'gh-' + number;
  const link = String(it.html_url || it.url || '');
  if (seenId.has(entry) || (link && seenLink.has(link))) continue;
  seenId.add(entry);
  if (link) seenLink.add(link);
  rows.push({
    json: {
      ENTRY_ID: entry,
      TOPIC: String(it.title || '').trim(),
      DESCRIPTION: String(it.body || '').trim(),
      LINK: link,
      CATEGORIES: cfg.categories,
      ASSET_TYPES: cfg.asset_types,
      MAX_WORDS: cfg.max_words,
      PRIORITY: cfg.priority,
      AUDIENCE: cfg.audience,
      ORIGIN: 'BOARD',
      STATUS: 'QUEUE',
      UPDATE_DATE: runAt,
    },
  });
}

const titles = rows.map((r) => String(r.json.TOPIC).slice(0, 60));
console.log('build_intake_rows: ' + rows.length + ' new of ' + issues.length + ' issue(s) read');
for (const t of titles.slice(0, 10)) console.log('  add ' + t);

// One item even when nothing is new: if_has_new needs an input to branch on, and the
// downstream ceiling still has to run. Every real row carries the same NEW_COUNT so the
// append receives all of them.
if (!rows.length) return [{ json: { NEW_COUNT: 0, NEW_TITLES: '' } }];
return rows.map((r) =>
  ({ json: { ...r.json, NEW_COUNT: rows.length, NEW_TITLES: titles.join(' | ') } })
);

// The article queue's own ceiling: a row still in play whose last update is older than
// cancel_after_days is cancelled. The clock is the row's own UPDATE_DATE - the last write a
// phase made - so a run that is genuinely working the row is never old enough; only a stuck
// run or an approval nobody answered reaches this. IN_PROGRESS is cancelled as well as QUEUE
// and WAITING_APPROVAL: "not maintain current thing" is the point, and setting
// ARTICLE_STATUS=CANCELLED is what stops the article lane resuming a claimed row it never
// finished.
const cfg = $('parse_board_config').first().json;
const days = Math.max(1, Number(cfg.cancel_after_days) || 7);
const nowMs = Date.parse(cfg.run_at) || Date.now();
const IN_PLAY = new Set(['QUEUE', 'IN_PROGRESS', 'WAITING_APPROVAL']);

const rows = $('read_article_queue').all().map((i) => i.json).filter((r) => r && r.row_number);
const stale = [];
for (const r of rows) {
  const status = String(r.STATUS || '').trim().toUpperCase();
  if (!IN_PLAY.has(status)) continue;
  const at = Date.parse(r.UPDATE_DATE || '');
  if (!isFinite(at)) continue;
  const age = (nowMs - at) / 86400000;
  if (age <= days) continue;
  stale.push({ row_number: r.row_number, TOPIC: r.TOPIC || '', STATUS: status, age: Math.round(age) });
}
const titles = stale.map((s) => String(s.TOPIC).slice(0, 60));
console.log('build_cancel_rows: ' + stale.length + ' of ' + rows.length + ' article_queue row(s) past the ' + days + 'd ceiling');
for (let i = 0; i < stale.length && i < 10; i++) {
  console.log('  cancel r' + stale[i].row_number + ' (' + stale[i].STATUS + ', ' + stale[i].age + 'd) ' + titles[i]);
}
// One item even when nothing qualifies, so if_has_cancels branches and the notice still runs.
if (!stale.length) return [{ json: { CANCELLED_COUNT: 0, CANCELLED_TITLES: '' } }];
return stale.map((s) => ({ json: { ...s, CANCELLED_COUNT: stale.length, CANCELLED_TITLES: titles.join(' | ') } }));

